create or replace function public.toolbox_issues_list_updates(p_workspace_id uuid,p_issue_id text) returns jsonb language sql stable security definer set search_path='' as $$ select case when not private.toolbox_issues_has_access(p_workspace_id) then '[]'::jsonb else coalesce((select jsonb_agg(private.toolbox_issue_update_json(u) order by u.created_at desc) from public.toolbox_issue_updates u where u.workspace_id=p_workspace_id and u.issue_id=p_issue_id::bigint),'[]'::jsonb) end $$; create or replace function public.toolbox_issues_add_update(p_workspace_id uuid,p_issue_id text,p_text text) returns jsonb language plpgsql security definer set search_path='' as $$ declare u public.toolbox_issue_updates%rowtype; begin if not private.toolbox_issues_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; if not exists(select 1 from public.toolbox_issues where workspace_id=p_workspace_id and id=p_issue_id::bigint and archived_at is null) then raise exception 'Issue not found' using errcode='P0002'; end if; if char_length(trim(coalesce(p_text,'')))=0 then raise exception 'update text required' using errcode='22023'; end if; insert into public.toolbox_issue_updates(workspace_id,issue_id,creator_user_id,text_body) values(p_workspace_id,p_issue_id::bigint,(select auth.uid()),left(trim(p_text),20000)) returning * into u; update public.toolbox_issues set updated_at=now(),version=version+1 where workspace_id=p_workspace_id and id=p_issue_id::bigint; insert into public.toolbox_issues_activity(workspace_id,entity_type,entity_id,actor_user_id,event_type) values(p_workspace_id,'issue',p_issue_id,(select auth.uid()),'comment_added'); return private.toolbox_issue_update_json(u); end $$; revoke execute on function public.toolbox_issues_list_updates(uuid,text),public.toolbox_issues_add_update(uuid,text,text) from public,anon; grant execute on function public.toolbox_issues_list_updates(uuid,text),public.toolbox_issues_add_update(uuid,text,text) to authenticated;;
